// Social Media screen texts. Keys are the English source strings of Flux Social (named placeholders: {n}),
// so the plugin's language packs translate them too; the dictionaries are generated by plugins/flx-social/tools/i18n.py.
import { normalizeLocale } from '@fluxwp/core';
import en from './i18n/en.json';
import tr from './i18n/tr.json';
import de from './i18n/de.json';
import es from './i18n/es.json';
import fr from './i18n/fr.json';
import ptBr from './i18n/pt-br.json';
import ja from './i18n/ja.json';
import zh from './i18n/zh.json';
import ar from './i18n/ar.json';
import ru from './i18n/ru.json';

const dicts: Record<string, Record<string, string>> = { en, tr, de, es, fr, 'pt-br': ptBr, ja, zh, ar, ru };

export type Params = Record<string, string | number>;
export type Translate = (source: string, params?: Params) => string;

/** {name} placeholders. */
function fill(text: string, params?: Params): string {
  return params ? text.replace(/\{(\w+)\}/g, (m, k: string) => (k in params ? String(params[k]) : m)) : text;
}

export function translator(locale: string): Translate {
  const d = dicts[normalizeLocale(locale)] ?? {};
  return (source, params) => fill(d[source] ?? source, params);
}
